insert into vinculos(inmueble,persona,vinculo,desde)
select p.id,d.persona,d.vinculo,d.desde from d join propiedades p on upper(p.direccion)=upper(d.inmueble)
where exists (select 1 from personas x where x.id=d.persona)
  and not exists (select 1 from vinculos v where v.inmueble=p.id and v.persona=d.persona);

