insert into alquiler_pagos(contrato,periodo,importe,obs)
select d.contrato,d.periodo,d.importe,d.obs from d
where exists (select 1 from contratos c where c.id=d.contrato)
on conflict (contrato,periodo) do nothing;

select (select count(*) from contratos) as contratos, (select count(*) from alquiler_pagos) as pagos_de_alquiler;   -- contratos: 49
